const m=path.match(/^\/v4\/spreadsheets\/([A-Za-z0-9_-]+)(?:\/values\/([^?]+)\?([^#]+)|\?fields=[^#]+)$/);
if(!m) throw new Error('Sheets destination denied');
o.sheet_id=m[1];
if(m[2]){
  o.range=decodeURIComponent(m[2]);
  if(!/^'[^!\r\n]+'!A[1-9][0-9]*:[A-Z]+[1-9][0-9]*$/.test(o.range)) throw new Error('Sheets range denied');
  if(o.method==='PUT' && m[3]==='valueInputOption=RAW' && Array.isArray(o.body?.values) && o.body.values.length===1 && Array.isArray(o.body.values[0])) { o.adapter='update'; o.values=o.body.values; }
  else if(o.method==='GET' && m[3]==='valueRenderOption=UNFORMATTED_VALUE') o.adapter='read';
  else throw new Error('Sheets operation denied');
} else { if(o.method!=='GET') throw new Error('Sheets metadata denied'); o.adapter='metadata'; }
return [{json:o}];

